import{_ as n,C as o,o as a,c as i,a3 as g,E as d,w as l,j as t,a as s}from"./chunks/framework.CwI_YTFT.js";const c="/versions/v0.19.97/screens/settings/settings_menu.png",p="/versions/v0.19.97/screens/settings/firmware_menu.png",h="/versions/v0.19.97/screens/settings/usb_devices.png",u="/versions/v0.19.97/screens/settings/usb_devices_power.png",m="/versions/v0.19.97/screens/settings/migrate_all_confirm.png",S="/versions/v0.19.97/screens/settings/migrate_all_progress.png",f="/versions/v0.19.97/screens/settings/migrate_all_summary.png",R=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"settings/index.md","filePath":"settings/index.md"}'),E={name:"settings/index.md"};function _(T,e,v,b,w,A){const r=o("ManualRelated");return a(),i("div",null,[e[1]||(e[1]=g('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>Settings belong to the S32 itself and stay the same in every project. Clock, default channel and the encoder button are per project, under <a href="./../projects/#project-settings">Project Settings</a>.</p><p>Open <a href="./../navigation/main-menu">Main Menu</a> → <strong>SETTINGS</strong>.</p><p><img src="'+c+'" alt="Settings menu" class="screen"></p><table tabindex="0"><thead><tr><th>Row</th><th>What it does</th></tr></thead><tbody><tr><td><a href="#note-names">NOTE NAMES</a></td><td>How notes are named on screen</td></tr><tr><td><a href="./storage-info">STORAGE INFO</a></td><td>Free space, microSD, compact and format</td></tr><tr><td><a href="#firmware">FIRMWARE</a></td><td>Version and firmware update</td></tr><tr><td><a href="#usb-devices">USB DEVICES</a></td><td>What&#39;s plugged into <strong>USB HOST</strong>, and the power it draws</td></tr><tr><td><a href="#migrate-all-projects">MIGRATE ALL PROJECTS</a></td><td>Updates every old project at once</td></tr></tbody></table><h2 id="note-names" tabindex="-1">Note Names <a class="header-anchor" href="#note-names" aria-label="Permalink to &quot;Note Names&quot;">​</a></h2><p><strong>MIDDLE C</strong> sets which octave number middle C shows as: <strong>C5</strong>, <strong>C4</strong>, <strong>C3</strong> (default) or <strong>C2</strong>. It changes every note name on screen: device parameters, Step Seq and Euclid notes, and <strong>POLY AT</strong> macros.</p><p>Black keys are always <strong>C#</strong>, <strong>E♭</strong>, <strong>F#</strong>, <strong>A♭</strong> and <strong>B♭</strong> (<strong>C#2</strong>, <strong>A♭3</strong>). A Scaler <strong>KEY</strong> uses key names: <strong>D♭</strong>, <strong>E♭</strong>, <strong>F#</strong>, <strong>A♭</strong>, <strong>B♭</strong>.</p><p><a href="./../navigation/controls#edit-a-value">Edit</a> <strong>MIDDLE C</strong>.</p><h2 id="firmware" tabindex="-1">Firmware <a class="header-anchor" href="#firmware" aria-label="Permalink to &quot;Firmware&quot;">​</a></h2><p><strong>VERSION</strong> shows the firmware on your S32. <strong>FIRMWARE UPDATE</strong> starts an update over USB.</p><p><img src="'+p+'" alt="Settings → FIRMWARE" class="screen"></p><h2 id="usb-devices" tabindex="-1">USB Devices <a class="header-anchor" href="#usb-devices" aria-label="Permalink to &quot;USB Devices&quot;">​</a></h2><p><strong>USB DEVICES</strong> lists everything plugged into <strong>USB HOST</strong>, each under its hub, with the power it asks for. It updates as you plug and unplug.</p><p><img src="'+h+'" alt="USB DEVICES: two hubs, a keyboard and a pad" class="screen"></p><p>At the bottom, <strong>TOTAL</strong> adds up every row, hubs included, and <strong>USB-C INPUT</strong> shows what your computer or charger offers. <strong>USB HOST</strong> supplies up to <strong>380 mA</strong>. If <strong>TOTAL</strong> is higher, plug your devices into a powered USB hub.</p><p><img src="'+u+'" alt="900 mA in total on a 1.5A charger" class="screen"></p><h2 id="migrate-all-projects" tabindex="-1">Migrate All Projects <a class="header-anchor" href="#migrate-all-projects" aria-label="Permalink to &quot;Migrate All Projects&quot;">​</a></h2><p>After a firmware update, some projects need updating. Loading one asks <strong>UPDATE PROJECT TO CURRENT VERSION?</strong> and updates just that one. <strong>MIGRATE ALL PROJECTS</strong> updates every project that needs it, on the S32 and on microSD.</p><ol><li>Select <strong>MIGRATE ALL PROJECTS</strong>. If the open project has unsaved changes, you&#39;re asked to save first.</li><li>The S32 checks your projects, then asks how many it will update. Press <strong>UPDATE</strong>, or <strong>BACK</strong> to leave them as they are.</li></ol><p><img src="'+m+'" alt="UPDATE 12 PROJECTS?" class="screen"></p><p><img src="'+S+'" alt="PROJECT 4 OF 12" class="screen"></p><p><img src="'+f+'" alt="UPDATED 10, SKIPPED 1, FAILED 1" class="screen"></p><table tabindex="0"><thead><tr><th>Count</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>UPDATED</strong></td><td>Rewritten for this firmware, same name and place</td></tr><tr><td><strong>SKIPPED</strong></td><td>Too old or too new to update. Nothing was written</td></tr><tr><td><strong>FAILED</strong></td><td>Couldn&#39;t be read or written. The project is left as it was</td></tr></tbody></table><p>Projects already up to date aren&#39;t counted. Wait for it to finish, with the microSD card in.</p><div class="warning custom-block"><p class="custom-block-title">Projects that can&#39;t be updated</p><p>The S32 updates projects from the previous firmware version only.</p><ul><li><strong>PROJECT NEEDS OLDER FIRMWARE FIRST</strong>: install the firmware in between, load the project once, then update again.</li><li><strong>PROJECT NEEDS NEWER FIRMWARE</strong>: update the S32.</li></ul></div>',26)),d(r,null,{default:l(()=>[...e[0]||(e[0]=[t("ul",null,[t("li",null,[t("a",{href:"./storage-info"},"Storage Info"),s(" — Free space, compact and format")]),t("li",null,[t("a",{href:"./../projects/"},"Project"),s(" — Clock, channel and encoder button")]),t("li",null,[t("a",{href:"./../getting-started/troubleshooting"},"Troubleshooting"),s(" — Settings and storage messages")])],-1)])]),_:1})])}const C=n(E,[["render",_]]);export{R as __pageData,C as default};
